"""Expose actual current board role/operator/profile evidence to the native guard."""
from pathlib import Path
import json,gzip,hashlib,struct,numpy as np
from .io_utils import read_json,read_jsonl,write_json,file_sha256,object_sha256
from .r_inner_prefix_v1 import array
from .board_middle_append_v1 import checked,require,ref
SCHEMA='rinkfit.current_native_board_source_qualification.v1'

def build(packet_path,output,*,current_source_guard):
 pp=Path(packet_path).resolve();out=Path(output).resolve();require(not (out/'manifest.json').exists(),'Immutable native qualification exists');p=read_json(pp);seen=set();g=read_json(current_source_guard);require(g['passed']and g['packet']==ref(pp),'Actual current Python source guard differs');b=p['source_only_board_successor'];qp=checked(b['qualification'],seen);q=read_json(qp);require(q['schema']=='rinkfit.current_board_middle_source_append.v1' and q['raw_rows']==22522 and q['qualified_rows']==15164 and q['frames']==192,'Unknown actual new board source qualification');require(not p.get('source_math_source_authority'),'Explicit math wrappers need their own authority consumer')
 arrays={k:array(p,k,pp.parent,seen)for k in p['arrays']};n=read_json(checked(b['parent_packet'],seen))['row_count'];active=(arrays['admission']==1)&(arrays['fit_role']==1);indices=[i for i,rid in enumerate(p['source_row_ids'])if active[i]and rid.startswith(('board_instance_native/','board_instance/','outer_native/'))];require(all(i>=n for i in indices)and len(indices)==15153,'New active recalled-ID coverage differs');proofs={r['source_row_id']:r for r in read_jsonl(checked(q['profile_proofs'],seen))};geometry={r['source_row_id']:r for r in read_jsonl(checked(q['geometry_compact'],seen))};queries={r['row_index']:r for r in p['queries']};cache={};npz={};frames=[];frameids={};ledger=[];profiles=[];dependencies=list(q['actual_dependencies'])+[ref(qp),ref(__file__),ref(current_source_guard),b['parent_packet']];recipepath=Path(q['profile_proofs']['file']).parents[2]/'board_middle_reuse_v1/cpu_middle_v1/recipe.json'
 # The actual frame manifests provide the current executed recipe location.
 for f in q['frame_counts']:
  pts=int(f['native_pts']);one=next(v for v in proofs.values()if int(v['native_pts'])==pts);memberpath=checked(one['current_exact_membership_ref'],seen);mf=memberpath.parent/'manifest.json';m=read_json(mf);rr=read_json(checked(m['recipe'],seen));recipepath=Path(m['recipe']['file']);require(rr['schema']=='rinkfit.exact_board_middle_current_CPU_role_operator_recipe.v1'and rr['actual_RGB_replay']and rr['old_query_and_UV_preserved']and rr['device']=='cpu'and not rr['frozen_visual_model_used'],'Actual current reader recipe differs');src=read_json(checked(m['source_frame_proof'],seen));receipt=m['native_receipt'];require(src['native_video_decode_receipt']==receipt and src['actual_native_RGB_sha256']==one['actual_RGB_sha256']==receipt['decoded_native_RGB_sha256'],'Original/current native RGB binding differs');frameids[pts]=len(frames);frames.append(dict(native_pts=pts,shot_id=m['shot_id'],native_receipt=receipt,actual_RGB_sha256=one['actual_RGB_sha256'],current_mask=m['current_mask'],source_frame_proof=m['source_frame_proof'],actual_frame_manifest=ref(mf),exact_membership=one['current_exact_membership_ref'],recipe=m['recipe']));dependencies +=[ref(mf),m['recipe'],m['source_frame_proof'],m['current_mask'],one['current_exact_membership_ref']];cache[pts]={r['source_row_id']:r for r in json.loads(gzip.open(memberpath,'rt',encoding='utf8').read())}
 recipe=read_json(recipepath);offsets=np.linspace(-3,3,49);out.mkdir(parents=True,exist_ok=True)
 for k,i in enumerate(indices):
  rid=p['source_row_ids'][i];pr=proofs[rid];ge=geometry[rid];pts=int(arrays['native_pts'][i]);mr=cache[pts][rid];phys=mr['physical_role_review'];op=mr['original_operator_review'];require(pr['qualified']and pr['combined_source_status']=='pass'and mr['new_status']=='pass'and phys['status']=='pass'and op['status']=='operator_pass','Per-ID source role/operator is not qualified');require(phys['source_recipe_sha256']==recipe['source_recipe_sha256']and mr['source_record_sha256']==pr['original_source_record_sha256'],'Actual source recipe/whole original row hash differs');uv=arrays['uv'][i];normal=arrays['profile_normal'][i];require(uv.tobytes()==np.asarray(pr['source_uv'],dtype='<f8').tobytes()==np.asarray(mr['current_uv'],dtype='<f8').tobytes()and normal.tobytes()==np.asarray(pr['normal'],dtype='<f8').tobytes(),'Actual original UV/normal differs');require(mr['actual_original_RGB_replay_max_abs_px']==0 and op['stored_profile_mean_replay_max_abs_px']==0,'Actual original49 estimator did not replay original mean')
  ir=pr['intensity_reference'];ip=checked(ir,seen);key=str(ip)
  if key not in npz:
   with np.load(ip,allow_pickle=False)as z:npz[key]=np.asarray(z[ir['array']],dtype='<f8')
  intensity=npz[key][int(ir['row_index'])];require(intensity.shape==(49,)and np.isfinite(intensity).all()and hashlib.sha256(intensity.tobytes()).hexdigest()==pr['actual_intensity_binary64_sha256']and object_sha256(intensity.tolist())==op['actual_profile_49_values_sha256'],'Original actual signed49 profile changed');qq=queries[i];require(np.array_equal(np.asarray(qq['alpha']),offsets)and np.allclose(np.asarray(qq['native_uv']),np.asarray(pr['seed_uv'])+offsets[:,None]*normal,rtol=0,atol=1e-10),'Packet did not consume original49 finite Query');require(np.max(abs(np.asarray(pr['seed_uv'])+float(pr['alpha'])*normal-uv))<1e-9 and pr['channel']==2 and pr['polarity']==1,'Original source mean does not come from stored finite profile')
  ev=phys['actual_material_evidence'];keep=('same_board_material_relation','top_entry_transition','actual_blue_material_component','actual_selected_band_colour','foot_fall_support_endpoints_uv','foot_profile_normal');pe={key:ev[key]for key in keep if key in ev};phys=dict(phys,actual_material_evidence=pe);dependencies +=[ir,pr['source_journal'],pr['current_exact_membership_ref'],op['frozen_peak_recipe']]+phys.get('evidence_refs',[]);profiles.append(intensity)
  ledger.append(dict(global_row=i,profile_row=k,frame_index=frameids[pts],source_row_id=rid,source_dataset_id=p['source_dataset_ids'][i],source_family_id=pr['source_family_id'],native_pts=pts,shot_id=p['shot_ids'][int(arrays['shot_index'][i])],material_index=int(arrays['material_index'][i]),physical_role=phys['material_role'],current_uv=uv.tolist(),normal=normal.tolist(),UV_binary64_sha256=hashlib.sha256(uv.tobytes()).hexdigest(),actual_profile_binary64_sha256=pr['actual_intensity_binary64_sha256'],seed_uv=pr['seed_uv'],alpha=pr['alpha'],normal_offsets=pr['normal_offsets'],channel=pr['channel'],polarity=pr['polarity'],original_source_record_sha256=pr['original_source_record_sha256'],original_source_journal=pr['source_journal'],current_exact_membership_ref=pr['current_exact_membership_ref'],physical_role_review=phys,original_operator_review=op,actual_original_RGB_replay_max_abs_px=mr['actual_original_RGB_replay_max_abs_px']))
 table=np.asarray(profiles,dtype='<f8');target=out/'actual_signed49.f64'
 if target.exists():require(file_sha256(target)==hashlib.sha256(table.tobytes()).hexdigest(),'Unfrozen profile materialization differs')
 else:table.tofile(target)
 ledgerpath=out/'qualified_rows.jsonl'
 if ledgerpath.exists():
  digest=hashlib.sha256()
  for r in ledger:digest.update((json.dumps(r,ensure_ascii=False,separators=(',',':'),allow_nan=False)+'\n').encode('utf8'))
  require(file_sha256(ledgerpath)==digest.hexdigest(),'Unfrozen role/operator ledger differs')
 else:
  with ledgerpath.open('w',encoding='utf8',newline='\n')as stream:
   for r in ledger:stream.write(json.dumps(r,ensure_ascii=False,separators=(',',':'),allow_nan=False)+'\n')
 unique={};
 for d in dependencies:
  path=checked(d,seen);unique[(str(path),d['sha256'])]=dict(file=str(path),sha256=d['sha256'])
 result=dict(schema=SCHEMA,source_packet=ref(pp),source_qualification=ref(qp),parent_packet=b['parent_packet'],current_source_guard=ref(current_source_guard),issuer=ref(__file__),public_function='rinkfit_joint.board_native_qualification_v1.build',recipe=ref(recipepath),count=len(ledger),original_raw_suffix_rows=q['raw_rows'],original_source_qualified_rows=q['qualified_rows'],exact_profile_alias_rows_not_double_counted=q['qualified_rows']-len(ledger),original_frame_count=q['frames'],old_raw_rows=n,raw_rows=p['row_count'],source_video_sha256='e8b53966d56e72f3842d92c3ecbe6e9cc7e4670b7d0c9bd12f58fd2cff5ad57d',time_base='1/12800',coordinate_domain='native_1920x1080_pixel_centres',membership_array_sha256={key:p['arrays'][key]['sha256']for key in('uv','native_pts','shot_index','kind','material_index','admission','fit_role','profile_normal')},source_row_ids_sha256=hashlib.sha256(json.dumps(p['source_row_ids'],ensure_ascii=False,separators=(',',':')).encode()).hexdigest(),source_dataset_ids_sha256=hashlib.sha256(json.dumps(p['source_dataset_ids'],ensure_ascii=False,separators=(',',':')).encode()).hexdigest(),qualified_rows_native=ref(out/'qualified_rows.jsonl'),actual_signed49=dict(**ref(out/'actual_signed49.f64'),dtype='<f8',shape=[len(ledger),49]),frames=frames,actual_dependencies=list(unique.values()),source_noise_W_or_sigma_issued=False,quality_accepted=False,all_active_recalled_IDs_covered=True,all_original_UV_and_failure_denominators_preserved=True)
 write_json(out/'manifest.json',result);return ref(out/'manifest.json')
